<div style="font-family:Arial,sans-serif;color:#1b1b1b;line-height:1.5;"><h2 style="color:#002c53;margin:0 0 12px;">Your Haarlem Festival Order</h2><p>Hello <?php echo htmlspecialchars((string) $customerName, ENT_QUOTES, 'UTF-8'); ?>,</p><p>Your order <strong>#<?php echo (int) $orderId; ?></strong> has been confirmed.</p><p>Your ticket PDF and invoice PDF are attached to this email.</p><ul style="padding-left:18px;margin:0;"><?php foreach ((array) $tickets as $ticket): ?><li><strong><?php echo htmlspecialchars((string) ($ticket['event_name'] ?? 'Event'), ENT_QUOTES, 'UTF-8'); ?></strong><br>Date: <?php echo htmlspecialchars((string) ($ticket['event_date'] ?? ''), ENT_QUOTES, 'UTF-8'); ?><br>Time: <?php echo htmlspecialchars((string) ($ticket['event_time'] ?? ''), ENT_QUOTES, 'UTF-8'); ?><br>Venue: <?php echo htmlspecialchars((string) ($ticket['venue'] ?? ''), ENT_QUOTES, 'UTF-8'); ?></li><?php endforeach; ?></ul><p><strong>Total:</strong> EUR <?php echo number_format((float) $total, 2); ?></p><p style="color:#555;">Haarlem Festival Team</p></div>
